def transform(grid):
    h, w = len(grid), len(grid[0])
    line = next((r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 1), None)
    if line is None:
        return [row[:] for row in grid]

    line_color = grid[line][0]
    other = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (1, line_color)]
    if not other:
        return [row[:] for row in grid]

    rs = [r for r, c in other]
    top, bottom = min(rs), max(rs)
    # Move the object so its nearest edge is adjacent to the full-width line.
    if bottom < line:
        dr = line - 1 - bottom
        beyond = top + dr - 1
    else:
        dr = line + 1 - top
        beyond = bottom + dr + 1

    out = [row[:] for row in grid]
    for r, c in other:
        out[r][c] = 1
    for r, c in other:
        out[r + dr][c] = grid[r][c]

    if 0 <= beyond < h:
        out[beyond] = [8] * w
    return out
